function requestLocation(){if(window.ReactNativeWebView){if(!state.nativeLocationActive){state.nativeLocationActive=true;window.ReactNativeWebView.postMessage(JSON.stringify({type:'START_LOCATION'}));}return;}if(!navigator.geolocation){state.pendingRoute=false;toast('Šis įrenginys nepalaiko vietos nustatymo.');return;}if(state.locationWatch!=null)return;state.locationWatch=navigator.geolocation.watchPosition(p=>onLocation(p.coords),e=>{state.pendingRoute=false;if(state.navigating){state.locationError=true;renderBottom();}if(state.resumeRecheck){state.resumeRecheck=false;state.routeUpdateError=true;renderBottom();}if(e.code===1&&state.locationWatch!=null){navigator.geolocation.clearWatch(state.locationWatch);state.locationWatch=null;}toast(e.code===1?'Vietos leidimas nesuteiktas.':'Nepavyko nustatyti vietos.');},{enableHighAccuracy:true,maximumAge:0,timeout:20000});}
